35	    option (google.api.method_signature) = "parent,shortcut";
36	  }
37	
38	  // UpdateShortcut updates a shortcut for a user.
39	  rpc UpdateShortcut(UpdateShortcutRequest) returns (Shortcut) {
40	    option (google.api.http) = {
41	      patch: "/api/v1/{shortcut.name=users/*/shortcuts/*}"
42	      body: "shortcut"
43	    };
44	    option (google.api.method_signature) = "shortcut,update_mask";
45	  }
46	
47	  // DeleteShortcut deletes a shortcut for a user.
48	  rpc DeleteShortcut(DeleteShortcutRequest) returns (google.protobuf.Empty) {
49	    option (google.api.http) = {delete: "/api/v1/{name=users/*/shortcuts/*}"};
50	    option (google.api.method_signature) = "name";
51	  }
52	}
53	
54	message Shortcut {
55	  option (google.api.resource) = {
56	    type: "memos.api.v1/Shortcut"
57	    pattern: "users/{username}/shortcuts/{shortcut}"
58	    singular: "shortcut"
59	    plural: "shortcuts"
60	  };

